// Verify HMAC signature
const crypto = require('crypto');
const body = $input.first().json;
const sig = $('Budget Webhook').first().binary?.data || $('Budget Webhook').first().headers['x-hmac-signature'];
const ts = $('Budget Webhook').first().headers['x-hmac-timestamp'];

if (!sig || !ts) throw new Error('Missing HMAC signature');
const expected = crypto.createHmac('sha256', process.env.EVENT_HMAC_SECRET)
  .update(ts + '.' + JSON.stringify(body)).digest('hex');
if (sig !== expected) throw new Error('HMAC verification failed');

return [{ json: body }];

const d = $input.first().json;
const pct = d.percentage || 0;
const emoji = pct >= 100 ? '🔴' : pct >= 80 ? '🟡' : '🟢';
return [{ json: {
  to: $env.OWNER_WA_NUMBER,
  body: `${emoji} *Budget Alert*\n\nBudget *${d.budgetName}* sudah ${pct}% terpakai.\nSisa: Rp${(d.remaining || 0).toLocaleString('id-ID')}\n\nBalas "ok" untuk konfirmasi.`
} }];
